#!/usr/bin/env python3
"""Offline synthetic residential IPv6 target planner and replay reconciler."""

import argparse
import hashlib
import ipaddress
import json
import math
import os
import re
import stat
import sys


MANIFEST_LIMIT = 1024 * 1024
RESPONSES_LIMIT = 96 * 1024 * 1024
RESPONSES_LINE_LIMIT = 300000
PHYSICAL_LINE_LIMIT = 4096
DOCUMENTATION_PREFIX = 0x20010DB8
ID_RE = re.compile(r"[A-Za-z][A-Za-z0-9_-]{0,31}\Z")
ROW_KEYS = {"probe_id", "received_ms", "target", "source", "type", "code"}
MANIFEST_KEYS = {
    "version", "seed", "low_count", "attempts", "spacing_ms", "timeout_ms",
    "windows",
}
WINDOW_KEYS = {"id", "start_ms", "scopes"}
SCOPE_KEYS = {"id", "prefix", "subnets"}


class Segment:
    __slots__ = (
        "window", "scope", "subnet", "base", "network", "canary_iids",
        "targets", "canary_hits", "internal", "external",
    )

    def __init__(self, window, scope, subnet, base, canary_iids):
        self.window = window
        self.scope = scope
        self.subnet = subnet
        self.base = base
        self.network = canonical_address(base) + "/64"
        self.canary_iids = canary_iids
        self.targets = []
        self.canary_hits = set()
        self.internal = set()
        self.external = set()


class LowTarget:
    __slots__ = (
        "value", "address", "internal_attempts", "external_attempts",
        "external_sources", "responded_attempts",
    )

    def __init__(self, value):
        self.value = value
        self.address = canonical_address(value)
        self.internal_attempts = set()
        self.external_attempts = set()
        self.external_sources = set()
        self.responded_attempts = set()


class Probe:
    __slots__ = (
        "id", "segment", "target_value", "target", "role", "slot",
        "attempt", "sent_ms", "deadline_ms", "low_target",
    )

    def __init__(self, probe_id, segment, target_value, target, role, slot,
                 attempt, sent_ms, deadline_ms, low_target=None):
        self.id = probe_id
        self.segment = segment
        self.target_value = target_value
        self.target = target
        self.role = role
        self.slot = slot
        self.attempt = attempt
        self.sent_ms = sent_ms
        self.deadline_ms = deadline_ms
        self.low_target = low_target

    def as_json(self):
        segment = self.segment
        return {
            "id": self.id,
            "window": segment.window,
            "scope": segment.scope,
            "subnet": segment.subnet,
            "target": self.target,
            "role": self.role,
            "slot": self.slot,
            "attempt": self.attempt,
            "sent_ms": self.sent_ms,
            "deadline_ms": self.deadline_ms,
        }


def reject_constant(value):
    raise ValueError("nonfinite JSON number")


def finite_float(value):
    result = float(value)
    if not math.isfinite(result):
        raise ValueError("nonfinite JSON number")
    return result


def unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate JSON key")
        result[key] = value
    return result


def parse_json(raw):
    """Decode one UTF-8 JSON value, rejecting extensions and duplicate keys."""
    try:
        text = raw.decode("utf-8")
        if text.startswith("\ufeff"):
            raise ValueError("UTF-8 BOM is not permitted")
        return json.loads(
            text,
            object_pairs_hook=unique_object,
            parse_constant=reject_constant,
            parse_float=finite_float,
        )
    except (ValueError, UnicodeError, RecursionError) as error:
        raise ValueError("invalid UTF-8 JSON") from error


def canonical_address(value):
    return str(ipaddress.IPv6Address(value))


def parse_ipv6_address(text):
    if not isinstance(text, str) or "%" in text or any(c.isspace() for c in text):
        raise ValueError("invalid IPv6 address")
    try:
        value = int(ipaddress.IPv6Address(text))
    except (ipaddress.AddressValueError, ValueError) as error:
        raise ValueError("invalid IPv6 address") from error
    if value >> 96 != DOCUMENTATION_PREFIX:
        raise ValueError("IPv6 address is outside 2001:db8::/32")
    return value


def parse_prefix(text):
    if not isinstance(text, str) or "%" in text or any(c.isspace() for c in text):
        raise ValueError("invalid IPv6 prefix")
    if text.count("/") != 1:
        raise ValueError("prefix must have an explicit length")
    address_text, length_text = text.split("/")
    if length_text not in ("56", "64"):
        raise ValueError("prefix length must be /56 or /64")
    value = parse_ipv6_address(address_text)
    length = int(length_text)
    host_bits = 128 - length
    if value & ((1 << host_bits) - 1):
        raise ValueError("prefix has nonzero host bits")
    return value, length


def require_integer(value, name, minimum, maximum):
    if type(value) is not int or not minimum <= value <= maximum:
        raise ValueError("invalid integer field: " + name)


def require_exact_keys(value, keys, name):
    if not isinstance(value, dict) or set(value) != keys:
        raise ValueError("invalid object: " + name)


def load_manifest(path):
    raw = read_regular_file(path, MANIFEST_LIMIT)
    value = parse_json(raw)
    require_exact_keys(value, MANIFEST_KEYS, "manifest")

    if type(value["version"]) is not int or value["version"] != 1:
        raise ValueError("manifest version must be 1")
    require_integer(value["seed"], "seed", 0, (1 << 64) - 1)
    require_integer(value["low_count"], "low_count", 1, 32)
    require_integer(value["attempts"], "attempts", 1, 3)
    require_integer(value["spacing_ms"], "spacing_ms", 1, 1000)
    require_integer(value["timeout_ms"], "timeout_ms", 1, 1000000)

    raw_windows = value["windows"]
    if not isinstance(raw_windows, list) or len(raw_windows) > 8:
        raise ValueError("invalid windows array")

    windows = []
    window_ids = set()
    total_segments = 0
    for raw_window in raw_windows:
        require_exact_keys(raw_window, WINDOW_KEYS, "window")
        window_id = raw_window["id"]
        if not isinstance(window_id, str) or ID_RE.fullmatch(window_id) is None:
            raise ValueError("invalid window ID")
        if window_id in window_ids:
            raise ValueError("duplicate window ID")
        window_ids.add(window_id)
        require_integer(raw_window["start_ms"], "start_ms", 0, 10 ** 12)

        raw_scopes = raw_window["scopes"]
        if not isinstance(raw_scopes, list) or len(raw_scopes) > 32:
            raise ValueError("invalid scopes array")
        scope_ids = set()
        selected_networks = set()
        segments = []
        for raw_scope in raw_scopes:
            require_exact_keys(raw_scope, SCOPE_KEYS, "scope")
            scope_id = raw_scope["id"]
            if not isinstance(scope_id, str) or ID_RE.fullmatch(scope_id) is None:
                raise ValueError("invalid scope ID")
            if scope_id in scope_ids:
                raise ValueError("duplicate scope ID in window")
            scope_ids.add(scope_id)

            prefix_base, prefix_length = parse_prefix(raw_scope["prefix"])
            subnets = raw_scope["subnets"]
            if not isinstance(subnets, list):
                raise ValueError("invalid subnets array")
            if any(type(subnet) is not int for subnet in subnets):
                raise ValueError("subnet must be an integer")
            if len(set(subnets)) != len(subnets):
                raise ValueError("duplicate subnet")
            if prefix_length == 56:
                if not 1 <= len(subnets) <= 256:
                    raise ValueError("invalid /56 subnet count")
                if any(not 0 <= subnet <= 255 for subnet in subnets):
                    raise ValueError("invalid /56 subnet")
            elif subnets != [0]:
                raise ValueError("a /64 scope must select exactly subnet 0")

            for subnet in sorted(subnets):
                base = prefix_base + (subnet << 64)
                if base in selected_networks:
                    raise ValueError("overlapping selected /64 networks")
                selected_networks.add(base)
                segments.append({
                    "scope": scope_id,
                    "subnet": subnet,
                    "base": base,
                })
                total_segments += 1
                if total_segments > 2048:
                    raise ValueError("too many selected /64 networks")

        segments.sort(key=lambda segment: (segment["scope"], segment["subnet"]))
        windows.append({
            "id": window_id,
            "start_ms": raw_window["start_ms"],
            "segments": segments,
        })

    windows.sort(key=lambda window: window["id"])
    return {
        "seed": value["seed"],
        "low_count": value["low_count"],
        "attempts": value["attempts"],
        "spacing_ms": value["spacing_ms"],
        "timeout_ms": value["timeout_ms"],
        "windows": windows,
    }


def read_regular_file(path, maximum):
    if path == "-":
        raise ValueError("standard input is not an input file")
    try:
        info = os.stat(path)
        if not stat.S_ISREG(info.st_mode):
            raise ValueError("input is not a regular file")
        if info.st_size > maximum:
            raise ValueError("input file is too large")
        with open(path, "rb") as stream:
            if not stat.S_ISREG(os.fstat(stream.fileno()).st_mode):
                raise ValueError("input is not a regular file")
            raw = stream.read(maximum + 1)
    except (OSError, ValueError) as error:
        if isinstance(error, ValueError):
            raise
        raise ValueError("cannot read input file") from error
    if len(raw) > maximum:
        raise ValueError("input file is too large")
    return raw


def canary_values(seed, window, scope, network):
    material = (
        "ipv6-evidence-v1\n" + str(seed) + "\n" + window + "\n" +
        scope + "\n" + network + "\n"
    ).encode("ascii")
    c0 = int.from_bytes(hashlib.sha256(material).digest()[:8], "big")
    c0 |= 1 << 63
    return c0, c0 ^ 1


def construct_plan(model):
    probes = []
    segments = []
    low_count = model["low_count"]
    attempts = model["attempts"]
    spacing = model["spacing_ms"]
    timeout = model["timeout_ms"]

    for window in model["windows"]:
        window_id = window["id"]
        ordinal = 0
        for description in window["segments"]:
            scope = description["scope"]
            subnet = description["subnet"]
            base = description["base"]
            network = canonical_address(base) + "/64"
            canaries = canary_values(model["seed"], window_id, scope, network)
            segment = Segment(window_id, scope, subnet, base, canaries)
            segments.append(segment)
            id_prefix = window_id + "/" + scope + "/" + str(subnet) + "/"

            for iid in range(1, low_count + 1):
                target_value = base | iid
                low_target = LowTarget(target_value)
                segment.targets.append(low_target)
                for attempt in range(attempts):
                    sent = window["start_ms"] + ordinal * spacing
                    probe_id = (
                        id_prefix + "low-" + str(iid) + "/" + str(attempt)
                    )
                    probes.append(Probe(
                        probe_id, segment, target_value, low_target.address,
                        "low", iid, attempt, sent, sent + timeout, low_target,
                    ))
                    ordinal += 1

            for slot, iid in enumerate(canaries):
                target_value = base | iid
                target = canonical_address(target_value)
                for attempt in range(attempts):
                    sent = window["start_ms"] + ordinal * spacing
                    probe_id = (
                        id_prefix + "canary-" + str(slot) + "/" + str(attempt)
                    )
                    probes.append(Probe(
                        probe_id, segment, target_value, target, "canary",
                        slot, attempt, sent, sent + timeout,
                    ))
                    ordinal += 1
    return probes, segments


def make_plan(manifest_path):
    model = load_manifest(manifest_path)
    probes, _ = construct_plan(model)
    return {"version": 1, "probes": [probe.as_json() for probe in probes]}


def sorted_addresses(values):
    return [canonical_address(value) for value in sorted(values)]


def reconcile_segments(segments):
    output = []
    for segment in segments:
        overlap = segment.internal & segment.external
        if segment.canary_hits == {0, 1}:
            state = "alias_suspect"
        elif overlap:
            state = "ambiguous"
        else:
            state = "usable"

        if state != "usable":
            exposure = "excluded"
        elif segment.internal:
            exposure = "observed_internal_reply"
        else:
            exposure = "inconclusive"

        targets = []
        for low_target in segment.targets:
            internal_attempts = sorted(low_target.internal_attempts)
            external_attempts = sorted(low_target.external_attempts)
            if state == "alias_suspect":
                classification = "alias_suspect"
            elif state == "ambiguous":
                classification = "ambiguous"
            elif internal_attempts and external_attempts:
                classification = "mixed"
            elif internal_attempts:
                classification = "internal"
            elif external_attempts:
                classification = "external"
            else:
                classification = "unknown"

            # The plan always creates attempts consecutively from zero.
            attempt_count = max(
                1,
                max(
                    low_target.responded_attempts | low_target.internal_attempts |
                    low_target.external_attempts,
                    default=-1,
                ) + 1,
            )
            # Replaced by the actual plan-wide count below when necessary: all
            # unobserved attempts must remain silent, including high attempts.
            targets.append({
                "address": low_target.address,
                "classification": classification,
                "internal_attempts": internal_attempts,
                "external_attempts": external_attempts,
                "external_sources": sorted_addresses(low_target.external_sources),
                "silent_attempts": [
                    attempt for attempt in range(attempt_count)
                    if attempt not in low_target.responded_attempts
                ],
            })

        output.append({
            "window": segment.window,
            "scope": segment.scope,
            "subnet": segment.subnet,
            "network": segment.network,
            "state": state,
            "exposure": exposure,
            "canary_hits": sorted(segment.canary_hits),
            "internal": sorted_addresses(segment.internal),
            "external": sorted_addresses(segment.external),
            "overlap": sorted_addresses(overlap),
            "targets": targets,
        })
    return output


def open_responses(path):
    if path == "-":
        raise ValueError("standard input is not an input file")
    try:
        info = os.stat(path)
        if not stat.S_ISREG(info.st_mode):
            raise ValueError("input is not a regular file")
        if info.st_size > RESPONSES_LIMIT:
            raise ValueError("response file is too large")
        stream = open(path, "rb")
    except (OSError, ValueError) as error:
        if isinstance(error, ValueError):
            raise
        raise ValueError("cannot read response file") from error
    if not stat.S_ISREG(os.fstat(stream.fileno()).st_mode):
        stream.close()
        raise ValueError("input is not a regular file")
    return stream


def replay(manifest_path, responses_path):
    model = load_manifest(manifest_path)
    probes, segments = construct_plan(model)
    probe_by_id = {probe.id: probe for probe in probes}
    attempts = model["attempts"]

    accepted_rows = 0
    duplicate_rows = 0
    diagnostics = []
    accepted_tuples = set()
    total_bytes = 0
    line_number = 0

    stream = open_responses(responses_path)
    try:
        while True:
            raw = stream.readline(PHYSICAL_LINE_LIMIT + 1)
            if not raw:
                break
            total_bytes += len(raw)
            line_number += 1
            if total_bytes > RESPONSES_LIMIT:
                raise ValueError("response file is too large")
            if line_number > RESPONSES_LINE_LIMIT:
                raise ValueError("too many response lines")
            if len(raw) > PHYSICAL_LINE_LIMIT:
                raise ValueError("physical response line is too long")

            reason = None
            try:
                row = parse_json(raw)
            except ValueError:
                diagnostics.append({"line": line_number, "reason": "json"})
                continue

            if not isinstance(row, dict) or set(row) != ROW_KEYS:
                reason = "schema"
            elif (
                not isinstance(row["probe_id"], str) or
                not isinstance(row["target"], str) or
                not isinstance(row["source"], str) or
                not 1 <= len(row["probe_id"]) <= 200 or
                type(row["received_ms"]) is not int or
                type(row["type"]) is not int or
                type(row["code"]) is not int
            ):
                reason = "schema"

            if reason is None:
                try:
                    target_value = parse_ipv6_address(row["target"])
                    source_value = parse_ipv6_address(row["source"])
                except ValueError:
                    reason = "address"

            probe = None
            if reason is None:
                probe = probe_by_id.get(row["probe_id"])
                if probe is None:
                    reason = "unknown_probe"
            if reason is None and target_value != probe.target_value:
                reason = "target_mismatch"
            if reason is None and not (
                probe.sent_ms <= row["received_ms"] < probe.deadline_ms
            ):
                reason = "time"
            if reason is None:
                message_type = row["type"]
                code = row["code"]
                if not (
                    (message_type == 129 and code == 0) or
                    (message_type == 1 and 0 <= code <= 6)
                ):
                    reason = "icmp"

            if reason is not None:
                diagnostics.append({"line": line_number, "reason": reason})
                continue

            key = (
                probe.id, row["received_ms"], target_value, source_value,
                message_type, code,
            )
            if key in accepted_tuples:
                duplicate_rows += 1
                continue
            accepted_tuples.add(key)
            accepted_rows += 1

            segment = probe.segment
            is_echo = message_type == 129
            same_source = source_value == target_value
            if probe.role == "canary":
                if is_echo and same_source:
                    segment.canary_hits.add(probe.slot)
                continue

            low_target = probe.low_target
            attempt = probe.attempt
            low_target.responded_attempts.add(attempt)
            if is_echo and same_source:
                segment.internal.add(target_value)
                low_target.internal_attempts.add(attempt)
            elif not is_echo and not same_source:
                segment.external.add(source_value)
                low_target.external_attempts.add(attempt)
                low_target.external_sources.add(source_value)
    finally:
        stream.close()

    result_segments = reconcile_segments(segments)
    # Silent attempts cover the whole configured attempt range, not merely the
    # greatest attempt observed in the log.
    for segment_output, segment in zip(result_segments, segments):
        for target_output, low_target in zip(segment_output["targets"], segment.targets):
            target_output["silent_attempts"] = [
                attempt for attempt in range(attempts)
                if attempt not in low_target.responded_attempts
            ]

    return {
        "version": 1,
        "accepted_rows": accepted_rows,
        "duplicate_rows": duplicate_rows,
        "diagnostics": diagnostics,
        "segments": result_segments,
    }


def main():
    parser = argparse.ArgumentParser(add_help=False)
    if any(arg in {"-h", "--help"} for arg in sys.argv[1:]):
        parser.error("help switches are not supported")
    sub = parser.add_subparsers(dest="command", required=True)
    plan = sub.add_parser("plan", add_help=False)
    plan.add_argument("manifest")
    replay_parser = sub.add_parser("replay", add_help=False)
    replay_parser.add_argument("manifest")
    replay_parser.add_argument("responses")
    args = parser.parse_args()
    try:
        result = (
            make_plan(args.manifest) if args.command == "plan"
            else replay(args.manifest, args.responses)
        )
        output = json.dumps(result, separators=(",", ":"), allow_nan=False)
    except (ValueError, OSError, RecursionError) as error:
        print(str(error) or "invalid input", file=sys.stderr)
        return 2
    print(output)
    return 0


if __name__ == "__main__":
    sys.exit(main())
